local UIFishPoolActivityTaskCellNode = Class("UIFishPoolActivityTaskCellNode")
function UIFishPoolActivityTaskCellNode:__init() 
    self._data = nil
    self._parLuaScr = nil
end

function UIFishPoolActivityTaskCellNode:__delete()
    self._data = nil
    self._parLuaScr = nil
end

function UIFishPoolActivityTaskCellNode:Awake()    
end

function UIFishPoolActivityTaskCellNode:Start()
    SetButtonAction(self.BtnRefresh, Bind(self, self.OnBtnRefresh))
    SetButtonAction(self.FontStyleButton, Bind(self, self.OnBtnSub))
end

function UIFishPoolActivityTaskCellNode:Refresh(data, parLuaScr)
    if not data then
        return
    end
    self._parLuaScr = parLuaScr

    self._data = data
    self:FillSelf()
end

function UIFishPoolActivityTaskCellNode:FillSelf()
    CfUtils.SetActive(self.UIFX_FishPoolActivityTaskDialog11070301_CardNode, false)

    local vo = FishingUtils.GetFishingTaskVo(self._data.realTaskId)
    if not vo then
        return
    end

    local goodsVo = GoodsConfMgr:GetInstance():GetGoodsVoById(vo.taskContentId1)
    if goodsVo then
        CfUtils.FillImage(self.ImgFish, goodsVo.photoPath)
        CfUtils.FillImage(self.ImgQuality, GoodsUtils.GetFishBgByQualityType(goodsVo.quality, true))
        CfUtils.FillText(self.TextFishName, goodsVo.name)
    end

    CfUtils.FillText(self.TextTitle2, vo.desc1)
    local scr = CfUtils.GetLuaScr(self.CommonGoodsList, CommonGoodsList)
    if scr then
        local rewardData = FishingUtils.GetFishingTaskBaseRewards(self._data.realTaskId)
        scr:FreshBaseUI(rewardData, false)
    end

    local rewardData = FishingUtils.GetFishingTaskExtraRewards(self._data.realTaskId, self._data.curExtraRateId)
    CfUtils.SetActive(self.CommonGoodsList2, table.count(rewardData) > 0)
    CfUtils.SetActive(self.EmptyNode, table.count(rewardData) <= 0)

    if table.count(rewardData) > 0 then 
        scr = CfUtils.GetLuaScr(self.CommonGoodsList2, CommonGoodsList)
        if scr then
            scr:FreshBaseUI(rewardData, false)
        end
    end

    SetButtonAction(self.BtnExplain, function()
        GameUtils.ShowCommonTipsBoardTaskFish(self.BtnExplain, self._data.realTaskId, self._data.curExtraRateId)
    end)

    CfUtils.SetActive(self.FishGrade, checkNumber(self._data.highestRateId) > 0)
    CfUtils.SetActive(self.NoGrade, checkNumber(self._data.highestRateId) <= 0)

    if checkNumber(self._data.highestRateId) > 0 then
        CfUtils.SetUISwitchImage(self.ImgGrade, (self._data.highestRateId))
        CfUtils.SetUISwitchImage(self.ImgIcon, FishingUtils.GetFishRareNameByRare(self._data.highestRateId) == "S" and 2 or 1)
    end

    for i = 1, self.StarNode.childCount do
        local go = self.StarNode:GetChild(i - 1)
        if go then
            CfUtils.SetActive(go, false)
        end
    end

    for i = 1, checkNumber(vo.taskQuality) do
        local go = self.StarNode.transform:Find("go"..i)
        if not go then
            go = CfUtils.InstantiateGo(self.ImgStar, self.StarNode)
            go.name = "go"..i
        end

        CfUtils.SetActive(go, true)
    end

    local fontStyleButton = KTool.GetComponent(self.FontStyleButton.gameObject, typeof(CS.Game.Native.Common.FontStyleButton))
    if checkNumber(self._data.status) == 1 then
        fontStyleButton:ResetFontStyle("B6", localize("提交"))

    else
        fontStyleButton:ResetFontStyle("B18", localize("提交"))
    end
end

function UIFishPoolActivityTaskCellNode:OnBtnRefresh()
    local num = fishingComponent:GetRemainFreeRefreshTimes()
    if num <= 0 then
        local goodsVo = GoodsConfMgr:GetInstance():GetGoodsVoById(FishingUtils.GetTaskRefreshConst())

        GameUtils.SecondConfirm(localize("刷新后任务值重新开始记录,确认消耗_num__name_刷新该任务?", {_num_ = FishingUtils.GetTaskRefreshConstNum() , _name_ = goodsVo.name}), function()
            fishingComponent:FishingRefreshChallengeTaskReq(self._data.realTaskId, function(taskId)
                GoodsUtils.DrawRewards({ [1] = { goodsId = FishingUtils.GetTaskRefreshConst(), num = FishingUtils.GetTaskRefreshConstNum() * -1} })
                self._parLuaScr:FillSelf(taskId)
            end)
        end)
    else
        fishingComponent:FishingRefreshChallengeTaskReq(self._data.realTaskId, function(taskId)
            self._parLuaScr:FillSelf(taskId)
        end)
    end
end

function UIFishPoolActivityTaskCellNode:OnBtnSub()
    local num = fishingComponent:GetRemainTaskSubmitTimes()
    if num <= 0 then
        GameUtils.Toast(localize("剩余提交次数不足"))
        return
    end

    if checkNumber(self._data.status) == 2 then
        GameUtils.Toast(localize("该任务已完成"))
        return
    elseif checkNumber(self._data.status) == 0 then
        GameUtils.Toast(localize("该任务未完成"))
        return
    end

    fishingComponent:FishingChallengeTaskDrawReq(self._data.realTaskId, function(taskId, rewards)
        CS.Engine.UI.UIModule.OpenDialog({ id = Constants.UITypeIds.UICommonRewardPop, parameters = { rewards = rewards, cb = function()
            self._parLuaScr:FillSelf(taskId)
        end } })
    end)
end


function UIFishPoolActivityTaskCellNode:OnDestroy()
    self.controller = nil--luabehaviour 中CSharp对象
    self:Delete()
    self = nil
end

return UIFishPoolActivityTaskCellNode
